toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #0D0E12;
  font-family: "Cormorant Garamond, serif";
}

>gold = #E2C074;
>softWhite = #F9F7F2;
>darkBorder = #242834;

circle #outerCrest {
  at: center of canvas;
  size: 300px;
  fill: none;
  stroke: >darkBorder;
  stroke-width: 1px;
}

circle #innerCrest {
  at: center of canvas;
  size: 270px;
  fill: none;
  stroke: >gold;
  stroke-width: 1.5px;
}

text #monogramGlyph {
  at: center of #innerCrest;
  content: "R";
  font-size: 110px;
  font-weight: 400;
  color: >gold;
}

text #brandTitle {
  at: below #outerCrest offset 48px;
  content: "R O S T O V A";
  font-size: 22px;
  font-weight: 600;
  color: >softWhite;
}

text #brandSubtitle {
  at: below #brandTitle offset 14px;
  content: "HAUTE JOAILLERIE • PARIS";
  font-size: 10px;
  font-weight: 400;
  color: >gold;
}
